mapper.select:
SELECT
/* isry.subms.casemng.mapper.CaseMngSubmsMapper.selectCaseinqList - Lee SangHoon */ TT.* , A.UP_CMMNS_CD_VALUE AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , TO_CHAR(TT.FRST_REG_DT2, 'YYYY-MM-DD') AS FRST_REG_DT /* 등록일자 */ FROM ( SELECT T99.* FROM ( SELECT /*+ INDEX_DESC(T1 SEB100_PK)*/ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.FRST_REG_DT AS FRST_REG_DT2 /* 등록일자 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , C##RG.DEC_B64(T2.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /* 대상자명 */ , TO_CHAR(TO_DATE(REPLACE(T2.TRPR_BRTH_YMD, '-', '')), 'YYYY-MM-DD') AS TRPR_BRTH_YMD /* 대상자출생일자 */ , T2.SXDC_SE_CD AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T1.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , C##RG.DEC_B64(X.FLNM_ENCPT) AS PIC_NM_ENCPT /* 담당자명(주담당자기준) */ , Y.PIC_INST_NO AS PIC_INST_NO /* 담당기관(주담당자기준) */ , CASE WHEN X.JBPS_NM IS NOT NULL THEN X.JBPS_NM ELSE (SELECT TT1.CMMNS_CD_VALUE_NM FROM SAC100 TT1 WHERE TT1.CMMNS_CD_ID = 'JBPS_SE_CD' AND TT1.CMMNS_CD_VALUE = X.JBPS_SE_CD) END AS JBPS_NM /* 담당자직위명(주담당자기준) */ , X.JBPS_SE_CD AS JBPS_SE_CD /* 담당자직위구분코드(주담당자기준) */ , Z.INST_NM AS INST_NM /* 담당기관명(주담당자기준) */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , T2.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호 */ , T2.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수 */ , T1.CASE_BGNG_YMD AS CASE_BGNG_YMD , T1.CASE_TRMN_YMD AS CASE_TRMN_YMD , CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '01' THEN 'REG' /* 등록 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('02','03','06','12') THEN 'PRGRS' /* 진행 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 'TRMN' /* 종결 */ ELSE '' END AS STEP_SE , T2.RCPT_PIC_NO AS RCPT_PIC_NO , Z.CTPV_CD AS CTPV_CD , T1.ORGNL_CASE_MNG_NO AS ORGNL_CASE_MNG_NO , ROWNUM AS SEQ , (SELECT SRVC_EXCN_BIZ_NM FROM SDA420 A, SEB120 B WHERE ROWNUM = 1 AND A.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO AND B.CASE_MNG_NO(+) = T1.CASE_MNG_NO AND B.CASE_MNG_ODRNO(+) = T1.CASE_MNG_ODRNO AND (A.EXCN_BIZ_CL_SE_CD != '02' OR A.EXCN_BIZ_CL_SE_CD IS NULL) AND B.DEL_YN = 'N') AS SRVC_EXCN_BIZ_NM , T3.BGNG_YMD AS COMPL_BGNG_YMD , T3.END_YMD AS COMPL_END_YMD FROM SEB100 T1 , SEA200 T2 , SCA100 X , SEB150 Y , SAA000 Z , AFA330 T3 WHERE 1=1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND Z.INST_NO = Y.PIC_INST_NO AND X.ENFSN_NO = Y.CASE_PIC_NO AND Y.PCHPRS_YN = 'Y' AND Y.CASE_MNG_NO = T1.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T1.CASE_MNG_NO = T3.CASE_MNG_NO(+) AND T1.CASE_MNG_ODRNO = T3.CASE_MNG_ODRNO(+)
) T99 WHERE 1 = 1
AND T99.SEQ >= #{START_IDX} AND T99.SEQ <= #{LAST_IDX}
) TT, SAC100 A WHERE TT.CASE_PRGRS_STTS_SE_CD = A.CMMNS_CD_VALUE(+) AND 'CASE_PRGRS_STTS_SE_CD' = A.CMMNS_CD_ID(+)

choose.otherwise:

/* 등록일자 조회 */
AND T1.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND T1.FRST_REG_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')

choose.when:

AND (T1.CASE_MNG_NO, T1.CASE_MNG_ODRNO)
    IN (SELECT YY.CASE_MNG_NO,YY.CASE_MNG_ODRNO
        FROM SEB150 YY
        WHERE 1=1
        AND YY.PIC_INST_NO = #{INST_NOS[0]}

   )

choose.otherwise:

	                AND EXISTS (SELECT 1 FROM SEB150 YY
	                WHERE T1.CASE_MNG_NO = YY.CASE_MNG_NO
	                AND T1.CASE_MNG_ODRNO = YY.CASE_MNG_ODRNO
	                AND YY.PIC_INST_NO IN


                            #{item}

	                )

sql.if:

AND EXISTS (SELECT 1 FROM SEB120 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
  AND B.CASE_MNG_ODRNO  = T1.CASE_MNG_ODRNO
  AND B.DEL_YN         = 'N'
  AND B.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
)


AND EXISTS (SELECT 1 FROM AFA410 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
 AND B.CASE_MNG_ODRNO   = T1.CASE_MNG_ODRNO
 AND B.APRV_YN          = #{APRV_YN}
)


AND EXISTS (SELECT 1 FROM SEB510 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
  AND B.CASE_MNG_ODRNO  = T1.CASE_MNG_ODRNO
  AND B.DEL_YN         = 'N'
  AND B.RESRCE_NO = #{RESRCE_NO}
)
